-- QueueGo Market catalog phase 2: seafood, fruit and common fresh-market vegetables.
-- Source-backed identity/pack facts only. Retailer price/cost/stock/barcode is never imported.
-- Retailer pages/images remain review references only; image is NULL and image_status stays pending.

alter table public.market_master_products
  drop constraint if exists market_master_products_category_check;

alter table public.market_master_products
  add constraint market_master_products_category_check
  check (category in (
    'ผักสด','เห็ด','ผลไม้','เนื้อหมู','เนื้อวัว','ไก่ / เป็ด',
    'ปลา','กุ้ง','ปู','หอย','ปลาหมึก','อาหารทะเล','ไข่',
    'เต้าหู้ / เส้นสด / ลูกชิ้น','ของสดพร้อมปรุง','อาหารแช่เย็น / แช่แข็ง',
    'พริกแกง / เครื่องแกง','เครื่องปรุง / ซอส','ข้าวสาร / ธัญพืช','ของแห้ง',
    'อาหารปรุงสำเร็จ','ขนม / ของหวาน','เครื่องดื่ม','ของใช้ในครัวเรือน',
    'ดอกไม้ / ของไหว้','อื่น ๆ'
  ));

insert into public.market_master_products(
  slug,name_th,category,suggested_unit,suggested_pack_size,source_unit,
  source_url,source_name,source_note,retrieved_on,
  image,image_status,image_source,image_rights_evidence,active
)
